# Python 脚本: 批量创建设备实例
import yaml
from kubernetes import client, config

def create_bulk_devices(device_list):
    """
    批量创建 KubeEdge 设备实例

    device_list: [
        {"name": "sensor-001", "node": "edge-a", "slave_id": 1, "port": "/dev/ttyS0"},
        ...
    ]
    """
    # 加载 K8s 配置
    config.load_kube_config()
    custom_api = client.CustomObjectsApi()

    for device_config in device_list:
        device_manifest = {
            "apiVersion": "devices.kubeedge.io/v1beta1",
            "kind": "Device",
            "metadata": {
                "name": device_config["name"],
                "namespace": "default",
                "labels": {
                    "location": device_config.get("location", "unknown"),
                    "type": "modbus-sensor"
                }
            },
            "spec": {
                "deviceModelRef": {
                    "name": "temperature-humidity-sensor"
                },
                "nodeName": device_config["node"],
                "protocol": {
                    "modbus": {
                        "slaveID": device_config["slave_id"]
                    },
                    "serialPort": {
                        "port": device_config["port"],
                        "baudRate": 9600,
                        "dataBits": 8,
                        "parity": "N",
                        "stopBits": 1
                    }
                },
                "properties": [
                    {
                        "name": "temperature",
                        "visitors": {
                            "modbus": {
                                "register": "HoldingRegister",
                                "offset": 0,
                                "limit": 1,
                                "scale": 0.1
                            }
                        },
                        "collectCycle": 5000,
                        "reportCycle": 5000,
                        "reportToCloud": True
                    }
                ]
            }
        }

        try:
            custom_api.create_namespaced_custom_object(
                group="devices.kubeedge.io",
                version="v1beta1",
                namespace="default",
                plural="devices",
                body=device_manifest
            )
            print(f"✅ 创建设备: {device_config['name']}")
        except Exception as e:
            print(f"❌ 创建失败 {device_config['name']}: {e}")

# 使用示例
